#!/usr/bin/env bash
#
# set-limine-timeout.sh -- set the Limine boot menu timeout.
#
# Omarchy's Limine template (/usr/share/omarchy/default/limine/limine.conf)
# leaves `#timeout: 3` commented out, so Limine falls back to its 5s default.
# This sets `timeout: 2` in the live /boot/limine.conf (header only -- boot
# entries generated by limine-entry-tool / limine-snapper-sync are untouched).
#
# NOTE: `omarchy refresh limine` (omarchy-refresh-limine) overwrites
# /boot/limine.conf from the default template. Re-run this script afterwards.
#
# Usage:
#   ./set-limine-timeout.sh [seconds]   # default: 2

set -euo pipefail

TIMEOUT="${1:-2}"

if ! [[ "$TIMEOUT" =~ ^[0-9]+$ ]]; then
  echo "error: timeout must be a non-negative integer (seconds), got: $TIMEOUT" >&2
  exit 1
fi

# Privilege: prefer sudo in an interactive terminal, fall back to pkexec
# (agent / GUI context) per Omarchy skill rules.
run_privileged() {
  if [[ -n "${SUDO_USER:-}" ]] || sudo -n true 2>/dev/null; then
    sudo "$@"
  elif command -v pkexec >/dev/null 2>&1; then
    pkexec "$@"
  else
    sudo "$@"
  fi
}

if ! run_privileged test -f /boot/limine.conf; then
  echo "error: /boot/limine.conf not found (is Limine installed?)" >&2
  exit 1
fi

run_privileged sed -i -E "s/^#?timeout:.*/timeout: $TIMEOUT/" /boot/limine.conf

# If the file had no timeout line at all, prepend one.
if ! run_privileged grep -qE "^timeout:" /boot/limine.conf; then
  run_privileged sed -i "1i timeout: $TIMEOUT" /boot/limine.conf
fi

echo "Limine timeout set to ${TIMEOUT}s:"
run_privileged grep -nE "^#?timeout:" /boot/limine.conf
